function nav(t,l){return `<div class="nav-group"><button class="nav-group__toggle" type="button">${t.firm}</button><div class="nav-dropdown nav-dropdown--firm"><a href="${anchor('v2-founders')}">${t.firmPartners}</a><a href="${anchor('v4-why')}">${t.firmApproach}</a></div></div><div class="nav-group"><button class="nav-group__toggle" type="button">${t.services}</button><div class="nav-dropdown"><a href="${p}expertises/comptabilite.html">${l==='en'?'Compliance & accounting':'Conformité & comptabilité'}</a><a href="${p}expertises/conseil-gestion.html">${l==='en'?'Management & reporting':'Pilotage & reporting'}</a><a href="${p}expertises/social-paie.html">${l==='en'?'Payroll & HR':'Social & RH'}</a><a href="${p}expertises/creation-juridique.html">${l==='en'?'Legal & company formation':'Juridique & création'}</a><a href="${p}conseil-dirigeant.html">${l==='en'?'Owner-manager advisory':'Conseil au dirigeant'}</a><a href="${p}facturation-electronique.html">${l==='en'?'E-invoicing':'Facturation électronique'}</a></div></div><a href="${p}expert-comptable-international.html">International</a><div class="nav-group"><button class="nav-group__toggle" type="button">${t.resources}</button><div class="nav-dropdown nav-dropdown--right"><a href="${p}blog/index.html">${t.blog}</a><a href="${p}simulateurs/index.html">${t.tools}</a></div></div><a href="${anchor('contact')}">${t.contact}</a>`;}

