function bind(){const n=document.getElementById('nav');n?.querySelectorAll('.nav-group__toggle').forEach((b,i)=>{const g=b.closest('.nav-group'),d=g?.querySelector('.nav-dropdown');if(d){const id='nav-menu-'+i;d.id=id;b.setAttribute('aria-controls',id);b.setAttribute('aria-haspopup','true');b.setAttribute('aria-expanded','false')}b.onclick=e=>{e.stopPropagation();n.querySelectorAll('.nav-group.is-open').forEach(x=>{if(x!==g){x.classList.remove('is-open');x.querySelector('.nav-group__toggle')?.setAttribute('aria-expanded','false')}});const open=g.classList.toggle('is-open');b.setAttribute('aria-expanded',String(open))};b.onkeydown=e=>{if(e.key==='Escape'){g.classList.remove('is-open');b.setAttribute('aria-expanded','false');b.focus()}}});}
