        cards:[['Diagnostic des flux','Émission, réception, volumes, logiciels et organisation actuelle.'],['Préparation des outils','Compatibilité, plateforme et circulation de l’information.'],['Process internes','Rôles, validations, archivage et nouvelles habitudes de travail.'],['Accompagnement des équipes','Mise en œuvre progressive et suivi des points bloquants.']],
